        + "box-shadow:0 8px 24px rgba(15,23,42,.14);padding:4px;box-sizing:border-box;z-index:10;}"
        + ".ods-cal-dlist.open{display:block;}"
        + ".ods-cal-ditem{padding:6px 10px;border-radius:6px;font-size:calc(13px + var(--ts-fs-adj,0px));"
        + "color:#1F2937;cursor:pointer;text-align:center;}"
        + ".ods-cal-ditem:hover{background:#F3F4F6;}"
        + ".ods-cal-ditem.sel{background:#3B82F6;color:#fff;font-weight:600;}"
        + ".ods-cal-nav{cursor:pointer;color:#6B7280;padding:4px 10px;border-radius:8px;border:none;background:none;"
        + "font-size:calc(14px + var(--ts-fs-adj,0px));line-height:1;}"
        + ".ods-cal-nav:hover{background:#F3F4F6;}"
        + ".ods-cal-grid{display:grid;grid-template-columns:repeat(8,1fr);gap:2px;}"
        + ".ods-cal-grid.no-wk{grid-template-columns:repeat(7,1fr);}"
        + ".ods-cal-dow{color:#9CA3AF;font-size:calc(11px + var(--ts-fs-adj,0px));text-align:center;padding:4px 0;font-weight:600;}"
        + ".ods-cal-wk{color:#C3C8D0;font-size:calc(11px + var(--ts-fs-adj,0px));text-align:center;padding:7px 0;}"
        + ".ods-cal-day{text-align:center;padding:6px 0;border-radius:8px;cursor:pointer;color:#1F2937;"
        + "font-size:calc(13px + var(--ts-fs-adj,0px));}"
        + ".ods-cal-day:hover{background:#F3F4F6;}"
        + ".ods-cal-day.out{color:#C9CED6;}"
        + ".ods-cal-day.today{box-shadow:inset 0 0 0 1px #3B82F6;}"
        + ".ods-cal-day.sel{background:#3B82F6;color:#fff;}"
        + ".ods-cal-foot{display:flex;justify-content:space-between;padding:10px 4px 0;border-top:1px solid #F3F4F6;margin-top:8px;}"
