        + "background:none;border:none;padding:4px;}"
        + ".ods-cal-btn:hover{text-decoration:underline;}"
        + ".ods-cal-time-row{display:flex;justify-content:center;padding:8px 0 0;border-top:1px solid #F3F4F6;margin-top:8px;}"
        + ".ods-cal-time-in{border:1px solid #E5E7EB;border-radius:8px;padding:6px 10px;font-size:calc(13px + var(--ts-fs-adj,0px));"
        + "color:#1F2937;font-family:inherit;background:#fff;}"
        + "html[data-theme='dark'] .ods-cal-time-row{border-top-color:#374151;}"
        + "html[data-theme='dark'] .ods-cal-time-in{background:#0F172A;color:#E5E7EB;border-color:#374151;}"
        + "input[data-ods-date]{cursor:pointer;}"
        + "input[data-ods-date]::-webkit-calendar-picker-indicator{opacity:0;}"
        + "html[data-theme='dark'] .ods-cal-title{color:#F1F5F9;}"
        + "html[data-theme='dark'] .ods-cal-dtrig{color:#F1F5F9;}"
        + "html[data-theme='dark'] .ods-cal-dtrig:hover{background:#293548;}"
        + "html[data-theme='dark'] .ods-cal-dlist{background:#1E293B;border-color:#374151;box-shadow:0 10px 24px rgba(0,0,0,.5);}"
        + "html[data-theme='dark'] .ods-cal-ditem{color:#E5E7EB;}"
        + "html[data-theme='dark'] .ods-cal-ditem:hover{background:#293548;}"
        + "html[data-theme='dark'] .ods-cal-ditem.sel{background:#3B82F6;color:#fff;}"
        + "html[data-theme='dark'] .ods-cal-nav{color:#9CA3AF;}"
        + "html[data-theme='dark'] .ods-cal-nav:hover{background:#293548;}"
        + "html[data-theme='dark'] .ods-cal-day{color:#E5E7EB;}"
        + "html[data-theme='dark'] .ods-cal-day:hover{background:#293548;}"
        + "html[data-theme='dark'] .ods-cal-day.out{color:#374151;}"
        + "html[data-theme='dark'] .ods-cal-day.sel{background:#3B82F6;color:#fff;}"
        + "html[data-theme='dark'] .ods-cal-foot{border-top-color:#374151;}"
        + "html[data-theme='dark'] .ods-cal-btn{color:#60A5FA;}"
        /* โหมดมืด — โทนเทาตาม Design System (เหมือน dark block ของหน้าต่าง ๆ) */
        + "html[data-theme='dark'] .ods-btn{background:#0F172A;color:#E5E7EB;border-color:#374151;}"
        + "html[data-theme='dark'] .ods-btn.open{border-color:#60A5FA;box-shadow:0 0 0 3px rgba(96,165,250,.2);}"
        + "html[data-theme='dark'] .ods-btn .ods-txt.ods-ph{color:#9CA3AF;}"   /* เดิม #374151 ชนกับ border-color บรรทัดบน กลายเป็นข้อความ placeholder มืดจนมองไม่เห็นบนพื้น input มืด (1.73) */
        + "html[data-theme='dark'] .ods-list{background:#1E293B;border-color:#374151;box-shadow:0 10px 24px rgba(0,0,0,.5);}"
